#pragma once

// Program support for C++ code generated by basicc (target pc): variables with dynamic binding
// (D15), arrays, routine frames, error handling with RESUME, FOR loops, DATA, program start.
// The semantics match the reference interpreter (src/ir/interp.cpp).

#include <algorithm>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <functional>
#include <iostream>
#include <initializer_list>
#include <string>
#include <type_traits>
#include <utility>
#include <vector>

#include "rt_gfx.hpp"
#include "rt_gui.hpp"
#include "rt_pc.hpp"

#ifdef _WIN32
#include <fcntl.h>
#include <io.h>
#endif

namespace brt {

// ---- variables ---------------------------------------------------------------------------------
// One storage slot per variable; a VAR parameter points to the caller's variable (probe10).
template <class T>
class Var {
public:
    Var() = default;
    Var(const Var&) = delete;
    Var& operator=(const Var&) = delete;
    T& operator()() { return *p_; }

private:
    friend class Frame;
    T own_{};
    T* p_ = &own_;
};

template <class T>
struct Array {
    bool dimmed = false;
    std::vector<std::int32_t> upper;
    std::vector<T> data;
};

template <class T>
using ArrVar = Var<Array<T>>;

struct State {
    Output out;
    Files files;
    Keyboard kbd;
    Memory mem;
    Gfx gfx;
    Gui gui;
    void (*menuProc)() = nullptr;  // ON MENU GOSUB
    std::int32_t reserve = kReserveStart;  // RESERVE / FRE (D27)
    int err = 0;
    void (*onError)() = nullptr;
    int handlerDepth = 0;
    int base = 0;  // OPTION BASE
    int matBase = 1;  // MAT BASE
    int line = 0;
    std::uint32_t seed = 1;
    const std::pair<const char*, bool>* data = nullptr;
    std::size_t dataCount = 0;
    std::size_t dataPos = 0;
};

inline State rt;

// ---- control flow ------------------------------------------------------------------------------
struct EndProgram {};
struct Resume {
    int mode;  // 0 retry, 1 next, 2 label
    int label;
};
struct GotoLabel {
    int label;
};
struct Fatal {
    std::string message;
};

// ---- routine frames ----------------------------------------------------------------------------
// Saves variables on entry to a routine (parameters, LOCAL) and restores them on every exit.
class Frame {
public:
    Frame() = default;
    Frame(const Frame&) = delete;
    Frame& operator=(const Frame&) = delete;
    ~Frame() {
        for (auto it = restore_.rbegin(); it != restore_.rend(); ++it) (*it)();
    }

    template <class T>
    void local(Var<T>& v) {
        for (const void* s : saved_)
            if (s == &v) return;
        saved_.push_back(&v);
        restore_.push_back([&v, own = std::move(v.own_), p = v.p_]() mutable {
            v.own_ = std::move(own);
            v.p_ = p;
        });
        v.own_ = T();
        v.p_ = &v.own_;
    }

    template <class T>
    void param(Var<T>& v, T value) {
        local(v);
        *v.p_ = std::move(value);
    }

    template <class T>
    void ref(Var<T>& v, Var<T>& target) {
        T* t = target.p_;
        if (t == v.p_) return;  // already the same variable
        local(v);
        v.p_ = t;
    }

private:
    std::vector<const void*> saved_;
    std::vector<std::function<void()>> restore_;
};

// ---- arrays ------------------------------------------------------------------------------------
template <class T>
void dim(ArrVar<T>& a, std::initializer_list<std::int32_t> dims) {
    Array<T>& arr = a();
    if (arr.dimmed) throw Error{14};  // redimensioned array (probe9)
    std::size_t n = 1;
    arr.upper.clear();
    for (std::int32_t u : dims) {
        if (u < rt.base) throw Error{17};  // dim out of range
        arr.upper.push_back(u);
        n *= static_cast<std::size_t>(u - rt.base + 1);
        if (n > 16u * 1024 * 1024) throw Error{17};
    }
    arr.data.assign(n, T());
    arr.dimmed = true;
}

template <class T>
T& elem(ArrVar<T>& a, std::initializer_list<std::int32_t> ix) {
    Array<T>& arr = a();
    if (!arr.dimmed) throw Error{15};                       // array undimensioned
    if (ix.size() != arr.upper.size()) throw Error{18};     // wrong # of indices
    std::size_t index = 0, mul = 1, k = 0;
    for (std::int32_t i : ix) {
        if (i < rt.base || i > arr.upper[k]) throw Error{RT_ERR_INDEX};
        index += static_cast<std::size_t>(i - rt.base) * mul;
        mul *= static_cast<std::size_t>(arr.upper[k] - rt.base + 1);
        ++k;
    }
    return arr.data[index];
}

template <class T>
std::int32_t dimCount(ArrVar<T>& a) {
    const Array<T>& arr = a();
    if (!arr.dimmed) return 0;
    std::int32_t c = 1;
    for (std::int32_t u : arr.upper) c *= u - rt.base + 1;
    return c;
}

// ---- functions with any number of arguments ----------------------------------------------------
inline f64 max(std::initializer_list<f64> v) {
    f64 best = *v.begin();
    for (f64 x : v)
        if (compare(x, best) > 0) best = x;
    return best;
}
inline f64 min(std::initializer_list<f64> v) {
    f64 best = *v.begin();
    for (f64 x : v)
        if (compare(x, best) < 0) best = x;
    return best;
}
inline std::string max(std::initializer_list<std::string> v) {
    std::string best = *v.begin();
    for (const std::string& x : v)
        if (compare(x, best) > 0) best = x;
    return best;
}
inline std::string min(std::initializer_list<std::string> v) {
    std::string best = *v.begin();
    for (const std::string& x : v)
        if (compare(x, best) < 0) best = x;
    return best;
}

inline std::int32_t errValue() { return static_cast<std::int8_t>(static_cast<std::uint8_t>(rt.err & 0xFF)); }

// ---- FOR (probe1 T18-T21, probe2 T10-T14) ------------------------------------------------------
// End and step are evaluated once; the condition is checked before the first pass; the variable
// is increased (integers wrap like INC) and the new value is checked.
inline bool forInRange(f64 v, f64 end, f64 step) {
    return compare(step, 0) < 0 ? compare(v, end) >= 0 : compare(v, end) <= 0;
}

inline bool forNext(f64& v, f64 end, f64 step) {
    v = add(v, step);
    return forInRange(v, end, step);
}

// width: 'i' Int, 'w' Word, 'b' Byte, '!' Bool
inline bool forNext(std::int32_t& v, f64 end, f64 step, char width) {
    const f64 next = add(flt(v), step);
    const f64 two31 = 0x41E0000000000000u, two32 = 0x41F0000000000000u;
    f64 t = fp_trunc(next);
    if (compare(t, two31) >= 0) t = sub(t, two32);
    else if (compare(t, fp_neg(two31)) < 0) t = add(t, two32);
    const std::int32_t i = toInt(t);
    v = width == 'w' ? wrapWord(i) : width == 'b' ? wrapByte(i) : width == '!' ? wrapBool(i) : i;
    return forInRange(next, end, step);
}

// ---- DATA, READ, RESTORE -----------------------------------------------------------------------
// A failing READ leaves the item to be read next (probe9 T1, T2).
inline const std::pair<const char*, bool>& dataItem() {
    if (rt.dataPos >= rt.dataCount) throw Error{34};  // out of data
    return rt.data[rt.dataPos];
}
inline f64 dataNumber() {
    const auto& d = dataItem();
    return dataNumber(d.first, d.second);
}
inline std::string dataString() { return dataItem().first; }
inline void dataNext() { ++rt.dataPos; }

// ---- ARRPTR, SWAP *p,a() (probe19): array descriptors in the emulated memory ---------------------
template <class T>
std::uint32_t arrDesc(Array<T>& a, int code, int width) {
    auto block = [&a, width]() -> std::uint32_t {
        if constexpr (std::is_same_v<T, std::string>) {
            return 0;  // string arrays: no block bytes
        } else {
            if (!a.dimmed) return 0;
            std::uint32_t first = 0;
            if constexpr (std::is_same_v<T, f64>) first = rt.mem.of(a.data, a.upper, rt.base, a.data[0]);
            else first = rt.mem.of(a.data, a.upper, rt.base, a.data[0], width);
            return first - static_cast<std::uint32_t>(4 * a.upper.size());
        }
    };
    auto dims = [&a]() { return a.dimmed ? static_cast<int>(a.upper.size()) : 0; };
    return rt.mem.descriptor(&a, code, block, dims);
}

template <class T>
void swapPtr(f64 p, Array<T>& a, int code) {
    int c = -1;
    const void* key = rt.mem.keyAt(p, c);
    if (key == nullptr || c != code) throw Error{68};  // var-type mismatch (ours)
    std::swap(*static_cast<Array<T>*>(const_cast<void*>(key)), a);
}

// ---- requesters and menus (D26) -------------------------------------------------------------------
inline void onMenu() {
    try {
        if (rt.gui.onMenu(rt.out) && rt.menuProc != nullptr) rt.menuProc();
    } catch (const Gui::EndOfInput&) {
        throw EndProgram{};  // no more events
    }
}

// ---- graphics (D25) -----------------------------------------------------------------------------
inline std::int32_t gfxInt(f64 v) { return toInt(fp_trunc(v)); }

// ---- MAT (D23): the same steps as the interpreter ------------------------------------------------
inline MatArray mat(Array<f64>& a) { return MatArray{a.data.data(), &a.upper, a.dimmed}; }
inline MatBase matBase() { return MatBase{rt.matBase, rt.base}; }
inline rt_mat matV(Array<f64>& a, bool column = false) { return matView(mat(a), matBase(), column); }
inline void matFill(Array<f64>& a, f64 x) { matFill(mat(a), matBase(), x); }
inline void matOne(Array<f64>& a) {
    const rt_mat m = matV(a);
    rt_mat_one(&m);
    check();
}
inline void matRead(Array<f64>& a) {
    const rt_mat m = matV(a);
    for (std::int32_t i = 0; i < m.rows; ++i)
        for (std::int32_t j = 0; j < m.cols; ++j) {
            matAt(m, i, j) = dataNumber();
            dataNext();
        }
}
inline void matInput(f64 channel, Array<f64>& a) {
    const rt_mat m = matV(a);
    for (std::int32_t i = 0; i < m.rows; ++i)
        for (std::int32_t j = 0; j < m.cols; ++j) matAt(m, i, j) = rt.files.inputNumber(channel);
}
inline void matPrint(Output& o, Array<f64>& a) { matPrint(o, matV(a), false, 0, 0); }
inline void matPrint(Output& o, Array<f64>& a, f64 g, f64 n) { matPrint(o, matV(a), true, g, n); }
inline void matCpy(Array<f64>& d, const std::vector<std::int32_t>& da, Array<f64>& s, const std::vector<std::int32_t>& sa,
                   std::int32_t h, std::int32_t w, bool transpose) {
    matCpy(mat(d), da, mat(s), sa, h, w, transpose, matBase());
}
inline void matTrans(Array<f64>& a, Array<f64>& b) {
    const rt_mat x = matV(a), y = matV(b);
    rt_mat_trans(&x, &y);
    check();
}
inline void matInv(Array<f64>& b, Array<f64>& a) {
    const rt_mat x = matV(b), y = matV(a);
    rt_mat_inv(&x, &y);
    check();
}
inline void matAddSub(Array<f64>& a, Array<f64>& b, Array<f64>& c, bool sub) {
    const rt_mat x = matV(a), y = matV(b), z = matV(c);
    rt_mat_addsub(&x, &y, &z, sub ? 1 : 0);
    check();
}
inline void matScalar(Array<f64>& a, f64 v, int op) {
    const rt_mat x = matV(a);
    rt_mat_scalar(&x, v, op);
    check();
}
inline void matMul(Array<f64>& a, Array<f64>& b, Array<f64>& c) {  // two vectors: outer product
    const bool vectors = b.upper.size() == 1 && c.upper.size() == 1;
    const rt_mat x = matV(a), y = matV(b, vectors), z = matV(c);
    rt_mat_mul(&x, &y, &z);
    check();
}
inline f64 matDot(Array<f64>& a, Array<f64>& b) {
    const rt_mat x = matV(a), y = matV(b);
    const f64 r = rt_mat_dot(&x, &y);
    check();
    return r;
}
inline f64 matTriple(Array<f64>& a, Array<f64>& b, Array<f64>& c) {
    const rt_mat x = matV(a), y = matV(b), z = matV(c);
    const f64 r = rt_mat_triple(&x, &y, &z);
    check();
    return r;
}
inline void matNorm(Array<f64>& a, std::int32_t byColumn) {
    const rt_mat x = matV(a);
    rt_mat_norm(&x, byColumn != 0 ? 1 : 0);
    check();
}
// kind 0 DET, 1 QDET, 2 RANG
inline f64 matDet(Array<f64>& a, const std::vector<std::int32_t>& at, std::int32_t n, int kind) {
    const rt_mat x = matSub(mat(a), matBase(), at, n);
    const f64 r = kind == 2 ? rt_mat_rank(&x) : rt_mat_det(&x, kind);
    check();
    return r;
}
inline void restore(std::size_t pos) { rt.dataPos = pos; }

// ---- error handling ----------------------------------------------------------------------------
// Called in the catch block of a statement: runs the error routine (ON ERROR GOSUB). Returns 0
// for RESUME (the statement again), 1 for RESUME NEXT, 2 + label for RESUME label.
inline int handle(const Error& e) {
    if (rt.onError == nullptr) throw e;
    rt.err = e.code;
    void (*proc)() = rt.onError;
    rt.onError = nullptr;  // the routine has to set ON ERROR GOSUB again
    ++rt.handlerDepth;
    try {
        proc();
    } catch (const Resume& r) {
        --rt.handlerDepth;
        rt.err = 0;  // RESUME clears ERR (probe12 T1)
        return r.mode == 2 ? 2 + r.label : r.mode;
    } catch (...) {
        --rt.handlerDepth;
        throw;
    }
    --rt.handlerDepth;
    throw Unhandled{e.code};  // the routine ended without RESUME: unhandled (probe12 T2)
}

// Condition of a header line (WHILE, IF, ELSE IF, DO WHILE/UNTIL) in a program with ON ERROR:
// an error belongs to that line (probe11, D19). RESUME evaluates it again, RESUME NEXT goes on with
// the first line of the body. Returns 1 (true), 0 (false), -1 (RESUME NEXT after an error).
template <class F>
int header(F f) {
    for (;;) {
        try {
            return isTrue(f()) ? 1 : 0;
        } catch (const Error& e) {
            const int r = handle(e);
            if (r == 0) continue;
            if (r == 1) return -1;
            throw GotoLabel{r - 2};
        }
    }
}

[[noreturn]] inline void resume(int mode, int label) {
    if (rt.handlerDepth == 0) throw Fatal{"RESUME outside the error routine"};
    throw Resume{mode, label};
}

// ---- program start -----------------------------------------------------------------------------
inline int run(const char* name, void (*program)(), const std::pair<const char*, bool>* data, std::size_t dataCount) {
    rt.kbd.in = &std::cin;
    rt.gui.in = &std::cin;
    rt.kbd.flush = [] {  // the prompt appears before the program waits
        std::fwrite(rt.out.buf.data(), 1, rt.out.buf.size(), stdout);
        std::fflush(stdout);
        rt.out.buf.clear();
    };
#ifdef _WIN32
    _setmode(_fileno(stdout), _O_BINARY);  // "\n" stays "\n"
#endif
    rt.gui.flush = rt.kbd.flush;
    rt.data = data;
    rt.dataCount = dataCount;
    randomize(rt.seed);
    int status = 0;
    std::string message;
    try {
        program();
    } catch (const EndProgram&) {
    } catch (const MemoryFault& m) {
        char buf[80];
        std::snprintf(buf, sizeof buf, "runtime error: memory access outside the BASIC data at $%08X", m.address);
        message = buf;
    } catch (const Error& e) {
        message = "runtime error " + std::to_string(e.code) + ": " + errorText(e.code);
    } catch (const Unhandled& e) {
        message = "runtime error " + std::to_string(e.code) + ": " + errorText(e.code);
    } catch (const Fatal& f) {
        message = "runtime error: " + f.message;
    } catch (const GotoLabel&) {
        message = "runtime error: GOTO target not reachable";
    } catch (const Resume&) {
        message = "runtime error: RESUME outside the error routine";
    }
    std::fwrite(rt.out.buf.data(), 1, rt.out.buf.size(), stdout);
    std::fflush(stdout);
    if (const char* gfxOut = std::getenv("BASIC_GFX_OUT"); gfxOut != nullptr && rt.gfx.used()) {  // D25
        if (std::FILE* f = std::fopen((std::string(gfxOut) + ".txt").c_str(), "w")) {
            const std::string d = rt.gfx.digest();
            std::fwrite(d.data(), 1, d.size(), f);
            std::fclose(f);
        }
        rt.gfx.writePpm(std::string(gfxOut) + ".ppm");
    }
    if (!message.empty()) {
        std::fprintf(stderr, "%s:%d: %s\n", name, rt.line, message.c_str());
        status = 1;
    }
    return status;
}

}  // namespace brt
